/**
 * A side bar component with Overlay
 * @example
 * ```jsx
 * <Aside type="search" heading="SEARCH">
 *  <input type="search" />
 *  ...
 * </Aside>
 * ```
 * @param {{
 *   children?: React.ReactNode;
 *   type: AsideType;
 *   heading: React.ReactNode;
 * }}
 */
export function Aside({children, heading, type}) {
  const {type: activeType, close} = useAside();
  const [isMounted, setIsMounted] = useState(false);
  const expanded = isMounted && type === activeType;

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (!isMounted) return;
    
    if (expanded) {
      document.body.classList.add('no-scroll');
    } else {
      document.body.classList.remove('no-scroll');
    }

    return () => {
      document.body.classList.remove('no-scroll');
    };
  }, [expanded, isMounted]);


  useEffect(() => {
    const abortController = new AbortController();

    if (expanded) {
      document.addEventListener(
        'keydown',
        function handler(event) {
          if (event.key === 'Escape') {
            close();
          }
        },
        {signal: abortController.signal},
      );
    }
    return () => abortController.abort();
  }, [close, expanded]);
// console.log(heading ,"jjjjj")
  return (
    <div
      aria-modal
      className={`overlay ${expanded ? 'expanded' : ''} ${
        heading === 'SEARCH' ? 'searchAsideComponent' : heading === 'MENU' ? 'menuAsideComponent' : heading === 'CART' ? 'cartAsideComponent' : ''
      }`}
      role="dialog"
    >
      {heading !== 'SEARCH' && (
        <button className="close-outside" onClick={close} />
      )}
      <aside className="aside-tag">
        {heading !== 'SEARCH' && (
          <header>
            {/* {CART ASIDE} */}
            {heading === 'CART' && <>{heading}</>}

            {/* {MENU ASIDE} */}
            {heading === 'MENU' && (
              <div className="flex h-full w-full items-center">
                <div className=" flex h-full items-center me-5 pe-1 border-e border_color_light">
                  <select name="country" id="country">
                    <option defaultValue="canada"> CANADA (CA $) </option>
                    <option value="uk">UNITED KINGDOM (GB £)</option>
                    <option value="us">UNITED STATES (US $)</option>
                    <option value="india">INDIA (INR ₹)</option>
                  </select>
                </div>
                <User className="w-5 h-5" />
              </div>
            )}

            {/* {SEARCH ASIDE} */}
            {heading === 'SEARCH' && <></>}

            <button className="close  reset" onClick={close} aria-label="Close">
              <X className="close_menu_icon aside_close_btn_effect" />
            </button>
          </header>
        )}
        <main>{children}</main>
      </aside>
    </div>
  );
}

const AsideContext = createContext(null);

Aside.Provider = function AsideProvider({children}) {
  const [type, setType] = useState('closed');

  return (
    <AsideContext.Provider
      value={{
        type,
        open: setType,
        close: () => setType('closed'),
      }}
    >
      {children}
    </AsideContext.Provider>
  );
};

export function useAside() {
  const aside = useContext(AsideContext);
  if (!aside) {
    throw new Error('useAside must be used within an AsideProvider');
  }
  return aside;
}

/** @typedef {'search' | 'cart' | 'mobile' | 'closed' | 'filter'} AsideType */
/**
 * @typedef {{
 *   type: AsideType;
 *   open: (mode: AsideType) => void;
 *   close: () => void;
 * }} AsideContextValue
 */

/** @typedef {import('react').ReactNode} ReactNode */
